#include <QtWidgets>
#include <QtTest/QTest>
#include "mainwindow.h"
#include "workspacehub.h"
#include "fontscale.h"
#include "calculatorthemes.h"
#include "i18n.h"
#include <iostream>
class DesktopAcceptanceTests {
public:
 int checks=0,failures=0;QJsonArray evidence;QString dir;
 void check(bool ok,QString what){++checks;if(!ok)++failures;std::cout<<(ok?"PASS ":"FAIL ")<<what.toStdString()<<"\n";}
 bool spin(std::function<bool()> done,int ms=15000){QElapsedTimer t;t.start();while(!done()&&t.elapsed()<ms){QCoreApplication::processEvents();QTest::qWait(5);}return done();}
 void capture(MainWindow&w,QString name){QCoreApplication::processEvents();QTest::qWait(20);const QString f=dir+"/"+name+".png";check(w.grab().save(f),"capture "+name);evidence.append(QJsonObject{{"file",name+".png"},{"width",w.width()},{"height",w.height()},{"mode",w.design_},{"theme",w.theme_},{"skin",w.calculatorTheme_},{"language",w.language_},{"font",w.fontSizeMode_},{"devicePixelRatio",w.devicePixelRatioF()},{"provenance",QString("native GNU/Linux Qt %1 %2").arg(qVersion(),QGuiApplication::platformName())}});}
 int probeFont(QString expected){MainWindow w(true);return w.fontSizeMode_==expected&&DesktopFont::sizeMode()==expected?0:1;}
 int skinSweep(QString output){dir=output;QDir().mkpath(dir);MainWindow w(true);w.show();check(spin([&]{return w.catalogReady_&&w.registersReady_;}),"skin sweep worker ready");w.designBox_->setCurrentIndex(w.designBox_->findData("Calculator"));if(w.settingsDraftActive_)w.applySettingsDraft();w.showPage(0);w.resize(320,540);for(const auto &skin:calculatorThemeNames()){w.calculatorThemeBox_->setCurrentIndex(w.calculatorThemeBox_->findData(skin));QCoreApplication::processEvents();check(w.calculatorTheme_==skin&&w.calculator_->calculatorTheme()==skin,"actual Calculator skin selector "+skin);capture(w,"skin-"+QString(skin).replace(' ','-').toLower());}QFile f(dir+"/skin-sweep.json");if(f.open(QIODevice::WriteOnly))f.write(QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures},{"captures",evidence},{"scope","Actual Settings selector used for all8skins; additional to full DPI acceptance run"}}).toJson());w.close();std::cout<<checks<<" skin checks, "<<failures<<" failures\n";return failures?1:0;}
 int run(QString output){dir=output;QDir().mkpath(dir);MainWindow w(true);w.show();check(spin([&]{return w.catalogReady_&&w.registersReady_;}),"catalog and registers ready");check(w.windowTitle()=="EMCICalc","exact title");check(w.input_->text().isEmpty()&&w.lastSerialized_.isEmpty(),"fresh profile blank");check(w.design_=="Desktop"&&w.minimumWidth()==680,"Desktop minimum");check(w.workbenchHub_->graphs->result().series.isEmpty(),"fresh graph has no sample result");capture(w,"desktop-fresh");
 // Actual keyboard routing and committed-value formatting.
 w.input_->setFocus();QTest::keyClicks(w.input_,"1/6");QTest::keyClick(w.input_,Qt::Key_Return);check(spin([&]{return !w.busy_&&!w.lastSerialized_.isEmpty();}),"keyboard Enter evaluates");check(w.lastSerialized_=="1/6","one sixth canonical");const int history=w.history_.size();const auto canonical=w.lastSerialized_;w.exactBox_->setCurrentIndex(1);check(spin([&]{return !w.formatPending_;}),"decimal format completes");check(w.lastSerialized_==canonical&&w.history_.size()==history,"format does not recommit");capture(w,"desktop-sixth");
 w.input_->setText("0/0");w.evaluate();check(spin([&]{return !w.busy_;}),"undefined evaluation ends");check(w.lastSerialized_.isEmpty(),"undefined no canonical value");check(w.history_.size()==history,"undefined no history commit");capture(w,"undefined");
 w.input_->setText("ln(0)");w.evaluate();check(spin([&]{return !w.busy_;}),"infinity evaluation ends");check(w.lastSerialized_=="-infinity","negative infinity succeeds");w.handleAction("@clear");check(w.input_->text().isEmpty()&&w.lastSerialized_.isEmpty(),"AC blanks active result");
 // Staged Desktop settings must not affect active preference until Apply.
 const auto original=w.fontSizeMode_;w.showPage(3);w.fontSizeBox_->setCurrentIndex(w.fontSizeBox_->findData("Large"));check(w.fontSizeMode_==original,"Desktop font staged");w.discardSettingsDraft();check(w.fontSizeMode_==original,"Cancel restores font");w.showPage(3);w.fontSizeBox_->setCurrentIndex(w.fontSizeBox_->findData("Large"));w.applySettingsDraft();check(w.fontSizeMode_=="Large","Apply commits font");capture(w,"desktop-settings-large");w.showPage(3);w.fontSizeBox_->setCurrentIndex(w.fontSizeBox_->findData("System"));w.applySettingsDraft();
 // Native in-window pages; capture every implemented destination.
 w.resize(1100,820);for(const auto&id:QStringList{"home","details","steps","guided","matrix","data","graphs","definitions","workflows","programmer","keypad"}){w.showWorkspace(id);
 if(id=="details"){w.input_->setText("1/6");w.evaluate();check(spin([&]{return !w.busy_&&!w.lastSerialized_.isEmpty();}),"manual Details example evaluated by actual worker");}
 if(id=="steps"){StepsRequest derivation;derivation.expression="x^2-5*x+6=0";derivation.operation="solve";w.workbenchHub_->steps->setRequest(derivation);auto *derive=w.workbenchHub_->steps->findChild<QPushButton*>("stepsDerive");check(derive!=nullptr,"native Derive action exists");if(derive)derive->click();check(spin([&]{return w.workbenchHub_->steps->findChild<QWidget*>("stepsAnswerCard")!=nullptr;}),"actual worker creates quadratic derivation");}
 QCoreApplication::processEvents();capture(w,"desktop-"+id);}
 
 w.showWorkspace("graphs");EmciGraph::Request request;request.bounds={-3,3,-3,3};EmciGraph::Series surface;surface.id="surface-proof";surface.expression="x^2-y^2";surface.kind=EmciGraph::Kind::Surface3D;request.series.append(surface);QString graphError;
 check(w.workbenchHub_->graphs->restoreState(EmciGraph::saveRequest(request),&graphError),"restore 3D configuration parse-only");w.workbenchHub_->graphs->requestPlot();check(spin([&]{return !w.workbenchHub_->graphs->result().series.isEmpty();},20000),"actual engine worker surface samples");check(!w.workbenchHub_->graphs->result().series.isEmpty()&&!w.workbenchHub_->graphs->result().series.first().triangles.isEmpty(),"native 3D mesh exists");capture(w,"desktop-graph3d");
 auto *canvas=w.workbenchHub_->graphs->findChild<QWidget*>("graphCanvas");if(canvas){auto before=canvas->grab().toImage();QTest::keyClick(canvas,Qt::Key_Right);QCoreApplication::processEvents();check(before!=canvas->grab().toImage(),"interactive surface rotation changes pixels");}
 request.series[0].kind=EmciGraph::Kind::Explicit;request.series[0].expression="sin(x)";check(w.workbenchHub_->graphs->restoreState(EmciGraph::saveRequest(request),&graphError),"restore curve configuration");w.workbenchHub_->graphs->requestPlot();check(spin([&]{return !w.workbenchHub_->graphs->result().series.isEmpty();},20000),"actual engine worker curve samples");capture(w,"desktop-graph");
 w.showPage(0);w.resize(680,540);capture(w,"desktop-minimum");
 for(const auto&theme:QStringList{"Graphite","Classic","Ocean","Forest","Amber","Rose","Porcelain","Aurora"}){w.theme_=theme;w.applyTheme();capture(w,"theme-"+theme.toLower());}
 w.theme_="Graphite";w.design_="Calculator";w.syncSettingsControls();w.applyDesign();w.resize(320,540);w.showPage(0);check(w.minimumWidth()==320,"Calculator minimum");
 for(const auto&skin:QStringList{"Classic","Shades of Grey","Modern Light","Modern Dark","Brushed Metal","Deep Ocean","AMOLED","Amber Terminal"}){w.calculatorThemeBox_->setCurrentIndex(w.calculatorThemeBox_->findData(skin));QCoreApplication::processEvents();check(w.calculatorTheme_==skin&&w.calculator_->calculatorTheme()==skin,"actual Calculator skin selector "+skin);capture(w,"skin-"+QString(skin).replace(' ','-').toLower());}
 w.calculatorThemeBox_->setCurrentIndex(w.calculatorThemeBox_->findData("Classic"));w.showPage(2);w.toolboxTabs_->setCurrentIndex(1);capture(w,"calculator-registers-small");w.resize(476,1600);capture(w,"calculator-registers-tall");
 w.resize(320,540);w.showWorkspace("matrix");capture(w,"calculator-matrix");w.showWorkspace("data");capture(w,"calculator-data");w.showWorkspace("graphs");capture(w,"calculator-graphs");
 for(auto lang:languageCodes()){w.language_=lang;w.updateTranslations();w.showPage(3);capture(w,"calculator-settings-"+lang);}
 w.language_="en";w.updateTranslations();w.showPage(3);w.fontSizeBox_->setCurrentIndex(w.fontSizeBox_->findData("Large"));check(w.fontSizeMode_=="Large","Calculator font immediate");capture(w,"calculator-large");w.showPage(0);w.resize(900,540);capture(w,"calculator-wide-large");
 for(const auto &preset:QStringList{"System","Small","Medium","Large"}){w.fontSizeBox_->setCurrentIndex(w.fontSizeBox_->findData(preset));check(w.saveSettings(),"font preference save "+preset);QProcess restored;restored.start(QCoreApplication::applicationFilePath(),{"--probe-font",preset,"--config-root",QFileInfo(w.configPath_).absolutePath()});check(restored.waitForFinished(15000)&&restored.exitCode()==0,"font process restoration "+preset);}
 QFile f(dir+"/manifest.json");check(f.open(QIODevice::WriteOnly),"capture manifest writable");f.write(QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures},{"captures",evidence}}).toJson());f.close();w.close();std::cout<<checks<<" checks, "<<failures<<" failures\n";return failures?1:0;
 }
};
int main(int argc,char **argv){QTemporaryDir profile;QVector<QByteArray> args;for(int i=0;i<argc;++i)args.append(argv[i]);if(!args.contains("--config-root")){args.append("--config-root");args.append(profile.path().toUtf8());}QVector<char*> pointers;for(auto &arg:args)pointers.append(arg.data());int count=pointers.size();pointers.append(nullptr);QApplication app(count,pointers.data());QApplication::setApplicationName("EMCICalc");DesktopFont::initialize(app);DesktopAcceptanceTests test;const auto options=QCoreApplication::arguments();const int probe=options.indexOf("--probe-font");if(probe>=0&&probe+1<options.size())return test.probeFont(options[probe+1]);if(options.contains("--skins-only"))return test.skinSweep(argc>1?argv[1]:"desktop-captures");return test.run(argc>1?argv[1]:"desktop-captures");}
